scripts.custom/zombie_basic/scripts/zombie-brain:
// The zombie's brain, ported from Dead Surge's zombie.ts with the room coupling
// stripped out: no lobby roster, no bricks, no rage shield, no exploder variant.
// What survives is what a Spawnable clone actually needs — walk to the nearest
// player, push off the neighbours, bite in range — plus the two rules the
// multiplayer model adds on top:
//
//   * ONLY client-sim values are params. `speed` is a param because every client
//     simulates its own positions anyway and nothing on the wire depends on it.
//     `hp` and `biteDamage` are NOT params: the server reads them from the Game
//     Config `zombie` table, so a script param would let the two diverge. The
//     editor's config-shadowing lint refuses to let you add them back.
//   * Damage is REPORTED, never applied. The bar shrinks when the server's
//     outcome ledger says it does — a few hundred milliseconds after the shot
//     landed. That delay is the honest price of server-tracked hit points.
//
// Draw-order note: nothing here is seeded. The spawn point and the wave the clone
// belongs to arrive from the Wave Director's plan; this file only simulates
// movement from there, which is why two clients agree on the alive-set and not on
// the trajectories.
import { Animator, Transform, engine, type Entity } from '@dcl/sdk/ecs'
import { Quaternion, Vector3 } from '@dcl/sdk/math'
import { isServer } from '@dcl/sdk/network'
import { outcomes, type OutcomeEntry } from './runtime/outcomes'
import { playerPositions } from './runtime/playerPositions'
import { spawnedFrom } from './runtime/spawner'

const ANIM_UP = 'ZombieUP'
const ANIM_WALK = 'ZombieWalk'
const ANIM_ATTACK = 'ZombieAttack'

/** The Wave Director arms its validators on this ledger; hits and bites ride it. */
const LEDGER = 'wave'
const ledger = outcomes(LEDGER)

const UP_DURATION_S = 1.2
const SEPARATION_WEIGHT = 0.35
const DEFAULT_HP = 40
const DEFAULT_BITE_COOLDOWN_S = 1.2
const BAR_MIN_SCALE = 0.001

// Every live brain on this client, so separation can read its neighbours without
// scanning the engine. Dead Surge kept the same list; here it is also what makes
// `release() ≡ fresh re-acquire` hold — detach() takes the clone back out.
const brains: ZombieBrain[] = []

type Globals = Record<string, unknown>

function record(value: unknown): Record<string, unknown> | null {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : null
}

// The generated src/scripts/game-config.ts publishes itself here. A prefab folder
// is self-contained by rule, so it cannot import that path — it reads the bag by
// shape, the same convention zoneBus uses.
function configSection(name: string): Record<string, unknown> {
  const bag = record((globalThis as unknown as Globals).__dclGameConfig_v1) ?? {}
  return record(bag[name]) ?? {}
}

function toNumber(value: unknown, fallback: number): number {
  if (typeof value === 'number') return Number.isFinite(value) ? value : fallback
  if (typeof value === 'string' && value.trim() !== '') {
    const parsed = Number(value)
    return Number.isFinite(parsed) ? parsed : fallback
  }
  return fallback
}

function distanceXZ(a: Vector3, b: Vector3): number {
  const dx = a.x - b.x
  const dz = a.z - b.z
  return Math.sqrt(dx * dx + dz * dz)
}

// Snapshot literals carry no core-schema::Name — a clone that kept the authored
// name would silently re-bind every name-keyed lookup in the scene. So the bar is
// found structurally instead: the root's only child, and that child's only child.
function firstChildOf(parent: Entity): Entity | null {
  for (const [entity, transform] of engine.getEntitiesWith(Transform)) {
    if (transform.parent === parent) return entity
  }
  return null
}

function playAnimation(entity: Entity, clip: string, loop: boolean, speed: number): void {
  const animator = Animator.getMutableOrNull(entity)
  if (animator === null) return
  for (const state of animator.states) {
    const active = state.clip === clip
    state.playing = active
    if (!active) continue
    state.loop = loop
    state.speed = speed
    state.shouldReset = true
  }
}

export class ZombieBrain {
  private instanceId = -1
  private clone = false
  private fill: Entity | null = null
  private resolved = false
  private state: 'rising' | 'walking' | 'attacking' = 'rising'
  private rising = 0
  private biteCooldown = 0
  private maxHp = DEFAULT_HP
  private hp = DEFAULT_HP
  private unsubscribe: (() => void) | null = null

  constructor(
    public src: string,
    public entity: Entity,
    /** Metres per second this clone walks. Client simulation only — every viewer runs its own. */
    public speed: number = 1.5,
    /** Metres from a player at which it stops walking and bites. */
    public attackRange: number = 1.4,
    /** Metres at which two clones start pushing each other apart. */
    public separationRadius: number = 0.95
  ) {}

  start(): void {
    // Clones only ever exist on clients; the placed anchor's copy would otherwise
    // walk an invisible zombie around the headless server for nothing.
    if (isServer()) return
    const from = spawnedFrom(this.entity)
    this.clone = from !== null
    this.instanceId = from === null ? -1 : from.instanceId
    this.maxHp = Math.max(1, Math.floor(toNumber(configSection('zombie').hp, DEFAULT_HP)))
    this.hp = this.maxHp
    brains.push(this)
    playAnimation(this.entity, ANIM_UP, false, 1)
    this.unsubscribe = ledger.onOutcome((entry) => this.applyOutcome(entry))
    for (const entry of ledger.snapshot()) this.applyOutcome(entry)
  }

  update(dt: number): void {
    if (isServer()) return
    if (!this.resolved) this.resolve()
    if (this.state === 'rising') {
      this.rising += dt
      if (this.rising < UP_DURATION_S) return
      this.walk()
      return
    }

    const here = Transform.getOrNull(this.entity)?.position ?? null
    if (here === null) return
    const target = this.nearestPlayer(here)
    if (target === null) return

    const distance = distanceXZ(here, target.position)
    if (distance <= this.attackRange) {
      this.bite(dt, target.local)
      return
    }
    if (this.state === 'attacking') this.walk()
    this.step(dt, here, target.position, distance)
  }

  // Release is delete-and-recreate for client-local pools, so a clone that leaves
  // must leave the neighbour list and the ledger subscription with it.
  detach(): void {
    const index = brains.indexOf(this)
    if (index >= 0) brains.splice(index, 1)
    this.unsubscribe?.()
    this.unsubscribe = null
  }

  // --- internals ------------------------------------------------------------

  private resolve(): void {
    this.resolved = true
    const bar = firstChildOf(this.entity)
    this.fill = bar === null ? null : firstChildOf(bar)
    this.paintBar()
  }

  private walk(): void {
    this.state = 'walking'
    playAnimation(this.entity, ANIM_WALK, true, 1)
  }

  private nearestPlayer(here: Vector3): { position: Vector3; local: boolean } | null {
    let best: { position: Vector3; local: boolean } | null = null
    let bestDistance = Number.POSITIVE_INFINITY
    for (const player of playerPositions()) {
      const distance = distanceXZ(here, player.position)
      if (distance >= bestDistance) continue
      bestDistance = distance
      best = { position: player.position, local: player.local }
    }
    return best
  }

  private bite(dt: number, localPlayer: boolean): void {
    if (this.state !== 'attacking') {
      this.state = 'attacking'
      playAnimation(this.entity, ANIM_ATTACK, true, 1)
    }
    this.biteCooldown -= dt
    if (this.biteCooldown > 0) return
    this.biteCooldown = Math.max(0.2, toNumber(configSection('zombie').biteCooldown, DEFAULT_BITE_COOLDOWN_S))
    // Only the bitten player reports the bite, and the report names the biter and
    // nothing else: the damage is the server's to decide from its own table.
    if (localPlayer && this.clone) ledger.report('bite', { instanceId: this.instanceId })
  }

  private step(dt: number, here: Vector3, target: Vector3, distance: number): void {
    const toward = Vector3.normalize(Vector3.create(target.x - here.x, 0, target.z - here.z))
    const push = distance > this.attackRange + 0.75 ? this.separation(here) : Vector3.Zero()
    const blended = Vector3.create(
      toward.x + push.x * SEPARATION_WEIGHT,
      0,
      toward.z + push.z * SEPARATION_WEIGHT
    )
    const lengthSq = blended.x * blended.x + blended.z * blended.z
    const direction = lengthSq > 0.0001 ? Vector3.normalize(blended) : toward
    const amount = Math.max(0, this.speed) * dt
    const transform = Transform.getMutableOrNull(this.entity)
    if (transform === null) return
    transform.position = Vector3.create(here.x + direction.x * amount, here.y, here.z + direction.z * amount)
    transform.rotation = Quaternion.lookRotation(direction)
  }

  private separation(here: Vector3): Vector3 {
    let pushX = 0
    let pushZ = 0
    const radius = Math.max(0.01, this.separationRadius)
    for (const other of brains) {
      if (other === this || other.state === 'rising') continue
      const there = Transform.getOrNull(other.entity)?.position
      if (there === undefined) continue
      const dx = here.x - there.x
      const dz = here.z - there.z
      const distanceSq = dx * dx + dz * dz
      if (distanceSq <= 0.0001 || distanceSq >= radius * radius) continue
      const distance = Math.sqrt(distanceSq)
      const strength = (radius - distance) / radius
      pushX += (dx / distance) * strength
      pushZ += (dz / distance) * strength
    }
    const lengthSq = pushX * pushX + pushZ * pushZ
    if (lengthSq <= 0.0001) return Vector3.Zero()
    const length = Math.sqrt(lengthSq)
    return Vector3.create(pushX / length, 0, pushZ / length)
  }

  // The bar is the ledger's view of this clone, not this client's guess: it moves
  // when the server has accepted a hit, which is slightly after the shot landed.
  private applyOutcome(entry: OutcomeEntry): void {
    if (entry.kind !== 'hit' || entry.instanceId !== this.instanceId) return
    this.hp = Math.max(0, entry.value)
    this.paintBar()
  }

  private paintBar(): void {
    if (this.fill === null) return
    const transform = Transform.getMutableOrNull(this.fill)
    if (transform === null) return
    const fraction = Math.max(BAR_MIN_SCALE, Math.min(1, this.hp / this.maxHp))
    transform.scale = Vector3.create(0.96 * fraction, transform.scale.y, transform.scale.z)
  }
}
